tool_calls:
cd /home/eval/pkgs; mkdir -p bin build; cat > bin/order <<'EOF'
#!/bin/bash
export LC_ALL=C
f=${1:?usage: order file}
awk '
{
  sub(/#.*/, ""); gsub(/\r/, "")
  i = index($0, ":"); if (i == 0) next
  p = substr($0, 1, i-1); r = substr($0, i+1)
  gsub(/[ \t]+/, "", p)
  if (p == "") next
  pk[p] = 1
  n = split(r, a, /[ \t:]+/)
  for (k = 1; k <= n; k++) {
    d = a[k]; if (d == "") continue
    pk[d] = 1
    if (!((p SUBSEP d) in seen)) {
      seen[p SUBSEP d] = 1
      cnt[p]++
      nd[d]++; dl[d, nd[d]] = p
    }
  }
}
END {
  for (x in pk) { total++; if (!(x in cnt)) ready[x] = 1 }
  out = 0
  while (1) {
    m = ""; have = 0
    for (x in ready) if (!have || x < m) { m = x; have = 1 }
    if (!have) break
    delete ready[m]; print m; done[m] = 1; out++
    for (k = 1; k <= nd[m]; k++) { q = dl[m, k]; if (--cnt[q] == 0) ready[q] = 1 }
  }
  if (out < total) {
    s = ""; c = 0
    for (x in pk) if (!(x in done)) rem[++c] = x
    # insertion-free sort via sort command
    cmd = "LC_ALL=C sort"
    for (k = 1; k <= c; k++) print rem[k] | cmd
    close(cmd)
    exit 1
  }
}' "$f" > >(cat) 2>/dev/null
EOF
echo

